<?php $e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');$posts=(array)($inbox['posts']??[]);$conversations=(array)($inbox['conversations']??[]);$access=(array)($inbox['message_access']??[]);$type=($type??'comments')==='messages'?'messages':'comments';$base='/social-inbox?connection_id='.(int)$selected.'&type=';?>
<style>.inbox-shell{display:grid;gap:10px}.inbox-head{display:flex;align-items:center;justify-content:space-between;gap:12px}.inbox-tabs{display:flex;gap:3px;padding:3px;border-radius:10px;background:#eef3f7}.inbox-tabs a{padding:7px 11px;border-radius:8px;color:#64778c;text-decoration:none;font-size:12px;font-weight:700}.inbox-tabs a.active{background:#fff;color:#244f78;box-shadow:0 2px 8px #17345212}.inbox-page-select{display:flex;align-items:center;gap:7px}.inbox-page-select label{font-size:11px;color:#6d7f93}.inbox-page-select select{min-width:210px}.inbox-list{display:grid;gap:6px}.inbox-item{padding:10px 12px;border:1px solid #e5ebf1;border-radius:10px;background:#fff}.inbox-meta{display:flex;align-items:center;justify-content:space-between;gap:8px;color:#748397;font-size:10px}.inbox-origin{margin:5px 0;color:#607389;font-size:10px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.inbox-message{margin:6px 0;color:#273d57;line-height:1.45}.inbox-row-actions{display:flex;align-items:center;gap:7px}.inbox-link{color:#28699f;font-size:10px;text-decoration:none}.inbox-reply{display:flex;gap:5px;flex:1}.inbox-reply input{flex:1;min-width:0;padding:7px 9px}.inbox-reply button{padding:7px 10px}.conversation{display:grid;grid-template-columns:36px minmax(0,1fr) auto;gap:9px;align-items:center}.conversation-avatar{display:grid;place-items:center;width:36px;height:36px;border-radius:50%;background:#e8f1f8;color:#356b96;font-weight:800}.conversation-main{min-width:0}.conversation-main strong,.conversation-main p{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.conversation-main p{margin:3px 0 0;color:#61748a;font-size:12px}.conversation time{color:#8492a3;font-size:10px}.conversation details{grid-column:2/-1}.conversation summary{cursor:pointer;color:#55718c;font-size:10px}.message-history{max-height:190px;overflow:auto;margin-top:7px;padding:8px;background:#f7f9fb;border-radius:8px}.message-history p{margin:4px 0;font-size:11px}.inbox-access{display:flex;gap:5px;flex-wrap:wrap}.inbox-access span{padding:3px 6px;border-radius:6px;background:#f1f4f7;font-size:9px}.inbox-access .ok{background:#e9f6ef;color:#23745a}.inbox-access .bad{background:#fff0f0;color:#a44750}@media(max-width:700px){.inbox-head{align-items:stretch;flex-direction:column}.inbox-page-select select{min-width:0;width:100%}.conversation{grid-template-columns:34px minmax(0,1fr)}}</style>
<section class="panel inbox-shell"><div class="inbox-head"><nav class="inbox-tabs" aria-label="Type de boîte de réception"><a class="<?= $type==='comments'?'active':''?>" href="<?= $e(route_url($base.'comments'))?>">Commentaires</a><a class="<?= $type==='messages'?'active':''?>" href="<?= $e(route_url($base.'messages'))?>">Messages</a></nav><form method="get" class="inbox-page-select"><input type="hidden" name="type" value="<?= $e($type)?>"><label>Page</label><select name="connection_id" onchange="this.form.submit()"><?php foreach($connections as$c):?><option value="<?= (int)$c['id']?>" <?= (int)$selected===(int)$c['id']?'selected':''?>><?= $e($c['account_label'])?></option><?php endforeach?></select></form></div><?php if($error):?><div class="flash error"><?= $e($error)?></div><?php endif?></section>
<?php if($type==='comments'):?><section class="panel" style="margin-top:10px"><div class="inbox-list"><?php if(!$posts):?><p>Aucun commentaire récent.</p><?php endif?><?php foreach($posts as$post):foreach((array)($post['comments']['data']??[])as$comment):$commentLink=trim((string)($post['permalink_url']??''));if($commentLink!=='')$commentLink.=(str_contains($commentLink,'?')?'&':'?').'comment_id='.urlencode((string)preg_replace('/^.*_/','',(string)($comment['id']??'')));?><article class="inbox-item"><div class="inbox-meta"><strong><?= $e($comment['from']['name']??'Auteur non communiqué')?></strong><time><?= $e(!empty($comment['created_time'])?date('d/m/Y H:i',strtotime($comment['created_time'])):'')?></time></div><div class="inbox-origin"><?= $e($inbox['connection']['account_label']??'')?> · <?= $e(mb_strimwidth((string)($post['message']??'Publication sans texte'),0,130,'…'))?></div><p class="inbox-message"><?= $e($comment['message']??'')?></p><div class="inbox-row-actions"><?php if($commentLink!==''):?><a class="inbox-link" href="<?= $e($commentLink)?>" target="_blank" rel="noopener">Facebook ↗</a><?php endif?><?php if($canReply):?><form method="post" action="<?= $e(route_url('/social-inbox/reply-comment'))?>" class="inbox-reply"><input type="hidden" name="connection_id" value="<?= (int)$selected?>"><input type="hidden" name="comment_id" value="<?= $e($comment['id']??'')?>"><input name="message" required placeholder="Répondre au commentaire…"><button class="button" type="submit">Envoyer</button></form><?php endif?></div></article><?php endforeach;endforeach?></div></section>
<?php else:?><section class="panel" style="margin-top:10px"><div class="inbox-head"><div class="inbox-access"><span class="<?= !empty($access['scope_granted'])?'ok':'bad'?>">pages_messaging</span><span class="<?= !empty($access['task_granted'])?'ok':'bad'?>">Tâche MESSAGING</span></div><?php if(!empty($inbox['message_error'])):?><a class="button secondary" href="<?= $e(route_url('/social-oauth/connect/'.(int)$selected))?>">Réactualiser les accès</a><?php endif?></div><?php if(!empty($inbox['message_error'])):?><div class="flash info"><?= $e($inbox['message_error'])?></div><?php endif?><div class="inbox-list"><?php if(!$conversations):?><p>Aucune conversation récente.</p><?php endif?><?php foreach($conversations as$conversation):$participants=(array)($conversation['participants']['data']??[]);$recipient='';$contact='Contact';foreach($participants as$p)if((string)($p['id']??'')!==(string)($inbox['connection']['external_account_id']??'')){$recipient=(string)$p['id'];$contact=(string)($p['name']??'Contact');break;}$messages=(array)($conversation['messages']['data']??[]);$latest=(array)($messages[0]??[]);?><article class="inbox-item conversation"><span class="conversation-avatar"><?= $e(mb_strtoupper(mb_substr($contact,0,1)))?></span><div class="conversation-main"><strong><?= $e($contact)?></strong><p><?= $e($latest['message']??'Conversation sans texte')?></p></div><time><?= $e(!empty($latest['created_time'])?date('d/m H:i',strtotime($latest['created_time'])):'')?></time><details><summary>Historique (<?= count($messages)?>)</summary><div class="message-history"><?php foreach(array_reverse($messages)as$message):?><p><strong><?= $e($message['from']['name']??'Utilisateur')?> :</strong> <?= $e($message['message']??'')?></p><?php endforeach?></div></details><?php if($canReply&&$recipient!==''):?><form method="post" action="<?= $e(route_url('/social-inbox/reply-message'))?>" class="inbox-reply" style="grid-column:2/-1"><input type="hidden" name="connection_id" value="<?= (int)$selected?>"><input type="hidden" name="recipient_id" value="<?= $e($recipient)?>"><input name="message" required placeholder="Répondre…"><button class="button" type="submit">Envoyer</button></form><?php endif?></article><?php endforeach?></div></section><?php endif?>
